body:
Hi!

I think I've solved this issue (I was also experiencing it in my large codebase, but can't reproduce it in a test yet -- hence the comment instead of a PR). Here's the relevant patch against `cf00a1a`:

``` diff
diff --git a/lib/ContextModule.js b/lib/ContextModule.js
index 92fd066..33f566e 100644
--- a/lib/ContextModule.js
+++ b/lib/ContextModule.js
@@ -5,7 +5,7 @@
 var Module = require("./Module");
 var OriginalSource = require("webpack-sources").OriginalSource;
 var RawSource = require("webpack-sources").RawSource;
-var DependenciesBlock = require("./DependenciesBlock");
+var AsyncDependenciesBlock = require("./AsyncDependenciesBlock");

 function ContextModule(resolveDependencies, context, recursive, regExp, addon, async) {
    Module.call(this);
@@ -80,12 +80,13 @@ ContextModule.prototype.build = function(options, compilation, resolver, fs, cal
            });
        }
        if(this.async) {
-           this.blocks = dependencies && dependencies.map(function(dep) {
-               var block = new DependenciesBlock();
-               block.parent = this;
-               block.dependencies = [dep];
-               return block;
-           }, this);
+           if(dependencies) {
+               dependencies.forEach(function(dep) {
+                   var block = new AsyncDependenciesBlock(null, dep.module, dep.loc);
+                   block.addDependency(dep);
+                   this.addBlock(block);
+               }, this);
+           }
        } else {
            this.dependencies = dependencies;
}
```

I _think_ the problem is that chunks were being retained across rebuilds. As a result, they weren't being re-added to the compilation chunk list [here](https://github.com/webpack/webpack/blob/ce76858334c47ec2ae08b6a9036e78fb31559333/lib/Compilation.js#L621-L633). `AsyncDependenciesBlock` removes the chunks on disconnect, fixing the problem.

This also fixed webpack/extract-text-webpack-plugin#188 for me.
